for (int i = 0; i < n_points; i++) {
    x = std::uniform_real_distribution<double>(a, b)(std::mt19937(seed));
    y = std::uniform_real_distribution<double>(0, fmax)(std::mt19937(seed));
    f_x = f(x);
    if (f_x > y) {
        n_hit++;
    }
    seed = (seed * 1664525 + 1013904223) % 4294967296U; // LCG update
}
return std::abs(b - a) * fmax * static_cast<double>(n_hit) / static_cast<double>(n_points);

